// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;

    function setUp() public { c = new PRIVATE_ETH_CELL(); }

    function testFuzz_property(address newLog) public {
        vm.assume(newLog != address(0));
        c.SetMinSum(1 ether);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        vm.prank(address(0x1234));
        bool ok;
        try c.SetLogFile(newLog) { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
}
